"use client"

import * as React from "react"
import { Toggle as TogglePrimitive } from "radix-ui"
import { cva, type VariantProps } from "class-variance-authority"
import "./minecraft-toggle-assets.css"
import { playMinecraftClick } from "./minecraft-sound"
import "./minecraft-toggle.css"

const toggleVariants = cva("mc-toggle", { variants: { variant: { default: "" }, size: { default: "" } }, defaultVariants: { variant: "default", size: "default" } })
type ToggleProps = React.ComponentProps<typeof TogglePrimitive.Root> & VariantProps<typeof toggleVariants> & { scale?: 1 | 2 | 3 }

function Toggle({ className, variant = "default", size = "default", scale = 2, style, children, asChild, disabled, onClick, onPointerDown, ...props }: ToggleProps) {
  if (variant !== "default" || size !== "default") throw new Error("Minecraft recipe filters support the default visual variant and size only")
  const child = asChild ? React.Children.only(children) as React.ReactElement<{children?: React.ReactNode}> : null
  return <TogglePrimitive.Root data-slot="toggle" asChild={asChild} disabled={disabled}
    className={toggleVariants({variant, size, className})}
    style={{"--mc-scale":scale,...style} as React.CSSProperties}
    {...props} aria-disabled={disabled ? true : props["aria-disabled"]}
    onPointerDown={event=>{if(disabled){event.preventDefault();return};onPointerDown?.(event)}}
    onClick={event=>{if(disabled||event.currentTarget.hasAttribute("data-disabled")||event.currentTarget.getAttribute("aria-disabled")==="true"){event.preventDefault();return};onClick?.(event);if(!event.defaultPrevented)playMinecraftClick()}}>
    {child ? React.cloneElement(child,undefined,child.props.children) : children}
  </TogglePrimitive.Root>
}

export { Toggle, toggleVariants }
export type { ToggleProps }

@layer components {
  .mc-toggle {
    --mc-scale: 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    vertical-align: middle;
    gap: calc(4px * var(--mc-scale));
    min-width: calc(26px * var(--mc-scale));
    min-height: calc(16px * var(--mc-scale));
    box-sizing: border-box;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: #fff;
    font: inherit;
    text-decoration: none;
    outline: none;
    box-shadow: none;
    appearance: none;
    opacity: 1;
    cursor: pointer;
    image-rendering: pixelated;
  }
  .mc-toggle::before {
    content: "";
    display: block;
    flex: 0 0 calc(26px * var(--mc-scale));
    width: calc(26px * var(--mc-scale));
    height: calc(16px * var(--mc-scale));
    background: var(--mc-toggle-off) center / 100% 100% no-repeat;
    image-rendering: pixelated;
  }
  .mc-toggle[data-state="on"]::before { background-image: var(--mc-toggle-on); }
  .mc-toggle:is(:hover, :focus-visible)::before { background-image: var(--mc-toggle-off-highlighted); }
  .mc-toggle[data-state="on"]:is(:hover, :focus-visible)::before { background-image: var(--mc-toggle-on-highlighted); }
  .mc-toggle:is(:disabled, [data-disabled], [aria-disabled="true"]) { cursor: default; }
}

import { minecraftClickSound } from "./minecraft-sound-assets"

let masterVolume = 1

/** Master volume from 0 (muted) to 1; native per-event gain stays unchanged. */
export function setMinecraftSoundVolume(volume: number) {
  if (Number.isFinite(volume)) masterVolume = Math.min(1, Math.max(0, volume))
}

export function getMinecraftSoundVolume() { return masterVolume }

/** Original ui.button.click, with SimpleSoundInstance.forUI's pitch and gain. */
export function playMinecraftClick() {
  if (typeof Audio === "undefined" || masterVolume === 0) return
  const sound = new Audio(minecraftClickSound)
  sound.volume = .25 * masterVolume
  sound.playbackRate = 1
  // A separate voice allows successive activations to overlap as in the game.
  void sound.play().catch(() => {})
}

"use client"

import * as React from "react"
import {ToggleGroup as ToggleGroupPrimitive} from "radix-ui"
import {toggleVariants} from "./toggle"
import {playMinecraftClick} from "./minecraft-sound"
import "./minecraft-toggle-group.css"

type Appearance={scale?:1|2|3;variant?:"default";size?:"default"}
type ToggleGroupProps=React.ComponentProps<typeof ToggleGroupPrimitive.Root>&Appearance&{spacing?:number}
type ToggleGroupItemProps=React.ComponentProps<typeof ToggleGroupPrimitive.Item>&Appearance
const AppearanceContext=React.createContext<Appearance&{disabled?:boolean}>({scale:2,variant:"default",size:"default"})

function ToggleGroup({scale=2,variant="default",size="default",spacing=2,className,style,children,disabled,...props}:ToggleGroupProps){
 if(variant!=="default"||size!=="default")throw new Error("Minecraft recipe filters support the default visual variant and size only")
 return <AppearanceContext.Provider value={{scale,variant,size,disabled}}><ToggleGroupPrimitive.Root data-slot="toggle-group" disabled={disabled} className={`mc-toggle-group ${className??""}`} style={{"--mc-scale":scale,"--mc-toggle-spacing":spacing,...style} as React.CSSProperties} {...props}>{children}</ToggleGroupPrimitive.Root></AppearanceContext.Provider>
}

function ToggleGroupItem({scale,variant,size,className,style,disabled,onClick,onPointerDown,...props}:ToggleGroupItemProps){
 const inherited=React.useContext(AppearanceContext),resolvedScale=scale??inherited.scale,resolvedVariant=variant??inherited.variant??"default",resolvedSize=size??inherited.size??"default",resolvedDisabled=disabled||inherited.disabled
 if(resolvedVariant!=="default"||resolvedSize!=="default")throw new Error("Minecraft recipe filters support the default visual variant and size only")
 return <ToggleGroupPrimitive.Item data-slot="toggle-group-item" disabled={resolvedDisabled} className={toggleVariants({variant:resolvedVariant,size:resolvedSize,className})} style={{"--mc-scale":resolvedScale,...style} as React.CSSProperties} {...props} aria-disabled={resolvedDisabled?true:props["aria-disabled"]}
 onPointerDown={event=>{if(resolvedDisabled||event.currentTarget.hasAttribute("data-disabled")){event.preventDefault();return};onPointerDown?.(event)}}
 onClick={event=>{if(resolvedDisabled||event.currentTarget.hasAttribute("data-disabled")||event.currentTarget.getAttribute("aria-disabled")==="true"){event.preventDefault();return};onClick?.(event);if(!event.defaultPrevented)playMinecraftClick()}}/>
}

export {ToggleGroup,ToggleGroupItem}
export type {ToggleGroupProps,ToggleGroupItemProps}
